import{_ as e,C as t,c as s,o as a,j as r,b as i,a0 as n,a as o,w as l,G as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Prise de décision fondée sur les probabilités","description":"","frontmatter":{},"headers":[],"relativePath":"fr/education/tactics/probability.md","filePath":"fr/education/tactics/probability.md"}');const p=e({name:"fr/education/tactics/probability.md"},[["render",function(e,c,p,h,b,m){const f=t("Mermaid");return a(),s("div",null,[c[1]||(c[1]=r("h1",{id:"prise-de-decision-fondee-sur-les-probabilites",tabindex:"-1"},[o("Prise de décision fondée sur les probabilités "),r("a",{class:"header-anchor",href:"#prise-de-decision-fondee-sur-les-probabilites","aria-label":'Permalink to "Prise de décision fondée sur les probabilités"'},"​")],-1)),c[2]||(c[2]=r("p",null,"La pensée tactique de haut niveau utilise les probabilités pour prendre de meilleures décisions. Au lieu de deviner ou de se fier à son intuition, on analyse systématiquement ses options.",-1)),c[3]||(c[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"La grande idée"),r("p",null,[r("strong",null,"Pensez en termes de probabilités, pas de certitudes."),o(" La meilleure décision n'est pas toujours la plus audacieuse ni la plus sûre ; c'est celle qui vous offre la meilleure valeur attendue dans de nombreuses situations similaires.")])],-1)),(a(),i(u,null,{default:l(()=>[d(f,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BPoint%20de%20d%C3%A9cision%5D%20--%3E%20B%5BOption%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOption%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOption%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BProbabilit%C3%A9%20de%20succ%C3%A8s%5D%0A%20%20%20%20B%20--%3E%20F%5BR%C3%A9compense%20en%20cas%20de%20succ%C3%A8s%5D%0A%20%20%20%20B%20--%3E%20G%5BCo%C3%BBt%20en%20cas%20d%26%2339%3B%C3%A9chec%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BProbabilit%C3%A9%20de%20succ%C3%A8s%5D%0A%20%20%20%20C%20--%3E%20I%5BR%C3%A9compense%20en%20cas%20de%20succ%C3%A8s%5D%0A%20%20%20%20C%20--%3E%20J%5BCo%C3%BBt%20en%20cas%20d%26%2339%3B%C3%A9chec%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BProbabilit%C3%A9%20de%20succ%C3%A8s%5D%0A%20%20%20%20D%20--%3E%20L%5BR%C3%A9compense%20en%20cas%20de%20succ%C3%A8s%5D%0A%20%20%20%20D%20--%3E%20M%5BCo%C3%BBt%20en%20cas%20d%26%2339%3B%C3%A9chec%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BValeur%20attendue%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BValeur%20attendue%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BValeur%20attendue%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BChoisissez%20le%20meilleur%20v%C3%A9hicule%20%C3%A9lectrique%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:l(()=>[...c[0]||(c[0]=[o(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=n('<h2 id="le-cadre-de-base" tabindex="-1">Le cadre de base <a class="header-anchor" href="#le-cadre-de-base" aria-label="Permalink to &quot;Le cadre de base&quot;">​</a></h2><p>Chaque lancer comporte trois composantes :</p><table tabindex="0"><thead><tr><th>Composant</th><th>Question</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Probabilité de succès</strong></td><td>Quelle est la probabilité que je réussisse à réaliser cela ?</td><td>Taux de réussite de 70 % à cette distance</td></tr><tr><td><strong>Récompense en cas de succès</strong></td><td>Qu&#39;est-ce que j&#39;y gagne ?</td><td>Gagnez le point, gagnez la position.</td></tr><tr><td><strong>Coût en cas d&#39;échec</strong></td><td>Qu&#39;est-ce que je perds ?</td><td>Offrir un point facile à l&#39;adversaire</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">La formule</p><p><strong>Valeur espérée = (Probabilité × Récompense) - ((1 - Probabilité) × Coût)</strong></p><p>Les bonnes décisions maximisent la valeur attendue au fil du temps.</p></div><h2 id="penser-en-termes-de-probabilites" tabindex="-1">Penser en termes de probabilités <a class="header-anchor" href="#penser-en-termes-de-probabilites" aria-label="Permalink to &quot;Penser en termes de probabilités&quot;">​</a></h2><p>Pour choisir entre les différentes options, tenez compte des éléments suivants :</p><ul><li>Quel est mon taux de réussite réaliste pour chaque option ?</li><li>Qu&#39;est-ce que j&#39;y gagne si ça marche ?</li><li>Quel sera le coût en cas d&#39;échec ?</li><li>Comment la situation de jeu influence-t-elle mon choix ?</li></ul><p>La meilleure option n&#39;est pas toujours la plus agressive ou la plus sûre ; c&#39;est celle qui donne le meilleur résultat dans de nombreuses situations similaires.</p><h2 id="connaissez-vos-chiffres" tabindex="-1">Connaissez vos chiffres <a class="header-anchor" href="#connaissez-vos-chiffres" aria-label="Permalink to &quot;Connaissez vos chiffres&quot;">​</a></h2><p>Pour utiliser le raisonnement probabiliste, vous devez connaître vos taux de réussite réels :</p><table tabindex="0"><thead><tr><th>Type de jet</th><th>Distance</th><th>Votre taux de réussite</th></tr></thead><tbody><tr><td>Point (proche)</td><td>6-7 m</td><td>___%</td></tr><tr><td>Point (moyen)</td><td>8-9 m</td><td>___%</td></tr><tr><td>Point (long)</td><td>10 m+</td><td>___%</td></tr><tr><td>Tir (rapprochement)</td><td>6-7 m</td><td>___%</td></tr><tr><td>Tir (moyen)</td><td>8-9 m</td><td>___%</td></tr><tr><td>Tourner (long)</td><td>10 m+</td><td>___%</td></tr></tbody></table><p>Suivez ces indicateurs en pratique. Soyez honnête : la plupart des joueurs surestiment leurs chances de réussite.</p><h2 id="ajustement-des-conditions" tabindex="-1">Ajustement des conditions <a class="header-anchor" href="#ajustement-des-conditions" aria-label="Permalink to &quot;Ajustement des conditions&quot;">​</a></h2><p>Vos tarifs de base varient en fonction de :</p><table tabindex="0"><thead><tr><th>Facteur</th><th>Effet sur le taux de réussite</th></tr></thead><tbody><tr><td>Terrain inconnu</td><td>-10 à -20%</td></tr><tr><td>Situation de pression</td><td>-5 à -15%</td></tr><tr><td>Fatigue</td><td>-5 à -10%</td></tr><tr><td>Confiance (élevée)</td><td>+5 à +10%</td></tr><tr><td>Succès récents</td><td>+5%</td></tr><tr><td>Échec récent</td><td>-5 à -10%</td></tr></tbody></table><p>Soyez réaliste quant à ces ajustements.</p><h2 id="le-principe-de-l-39-avantage-de-la-boule" tabindex="-1">Le principe de l&#39;avantage de la boule <a class="header-anchor" href="#le-principe-de-l-39-avantage-de-la-boule" aria-label="Permalink to &quot;Le principe de l&amp;#39;avantage de la boule&quot;">​</a></h2><p>Lorsque vous avez plus de boules restantes que votre adversaire :</p><p><strong>Priorité 1 : Sécuriser le point</strong></p><ul><li>Tout d&#39;abord, assurez-vous de détenir au moins un point</li><li>Ne soyez pas gourmand avant d&#39;avoir assuré les bases.</li></ul><p><strong>Priorité 2 : Maximiser les points avec un risque calculé</strong></p><ul><li>Une fois que vous tenez bon, évaluez si vous pouvez ajouter plus de points</li><li>Chaque lancer supplémentaire est une décision risque/récompense</li><li>Ne transformez pas une victoire assurée de 2 points en défaite en prenant des risques inconsidérés.</li></ul><p><strong>Il vous reste moins de boules :</strong> Chaque lancer compte. Les coups sûrs ne suffisent pas toujours ; privilégiez les options plus risquées pour revenir dans la partie.</p><h2 id="le-principe-quot-une-boule-devant-quot" tabindex="-1">Le principe &quot;Une Boule Devant&quot; <a class="header-anchor" href="#le-principe-quot-une-boule-devant-quot" aria-label="Permalink to &quot;Le principe &amp;quot;Une Boule Devant&amp;quot;&quot;">​</a></h2><p>Une boule placée devant le valet (entre le valet et l&#39;adversaire) est extrêmement précieuse :</p><ul><li>Il bloque les lignes pointant directement</li><li>Cela oblige les adversaires à contourner ou à passer par-dessus.</li><li>Il peut dévier les boules entrantes</li><li>C&#39;est une « boule d&#39;argent » — qu&#39;il faut protéger</li></ul><p><strong>Conséquences tactiques :</strong> Parfois, placer une boule de blocage est préférable à essayer de s&#39;approcher au plus près.</p><h2 id="tolerance-au-risque-selon-l-39-etat-du-jeu" tabindex="-1">Tolérance au risque selon l&#39;état du jeu <a class="header-anchor" href="#tolerance-au-risque-selon-l-39-etat-du-jeu" aria-label="Permalink to &quot;Tolérance au risque selon l&amp;#39;état du jeu&quot;">​</a></h2><h3 id="avec-une-limite-de-temps" tabindex="-1">Avec une limite de temps <a class="header-anchor" href="#avec-une-limite-de-temps" aria-label="Permalink to &quot;Avec une limite de temps&quot;">​</a></h3><p>Lorsqu&#39;on joue avec une limite de temps, l&#39;écart de score est important :</p><table tabindex="0"><thead><tr><th>Situation de score</th><th>Approche par les risques</th></tr></thead><tbody><tr><td>En tête avec plus de 4 points d&#39;avance</td><td>Très conservateur – protéger le plomb, faire tourner le chronomètre</td></tr><tr><td>En tête par 1-3</td><td>Conservateur - ne donnez pas de points</td></tr><tr><td>Lié</td><td>Équilibré - risques calculés</td></tr><tr><td>Mené de 1 à 3</td><td>Agressif – besoin de gagner du terrain</td></tr><tr><td>En retard de plus de 4 heures</td><td>Très agressif – il faut prendre des risques, le temps presse</td></tr></tbody></table><h3 id="sans-limite-de-temps" tabindex="-1">Sans limite de temps <a class="header-anchor" href="#sans-limite-de-temps" aria-label="Permalink to &quot;Sans limite de temps&quot;">​</a></h3><p>Quand il n&#39;y a pas de pression temporelle :</p><ul><li>Tenez-vous-en à votre plan de jeu – ne changez pas de stratégie simplement à cause du score</li><li>Le score fluctuera – faites confiance à votre approche.</li><li>N&#39;envisagez de changer de stratégie que si elle ne fonctionne manifestement pas contre cet adversaire.</li><li>Les changements de situation précipités lorsqu&#39;on est en retard ne font souvent qu&#39;empirer les choses.</li></ul><h3 id="ajustements-de-fin-de-partie" tabindex="-1">Ajustements de fin de partie <a class="header-anchor" href="#ajustements-de-fin-de-partie" aria-label="Permalink to &quot;Ajustements de fin de partie&quot;">​</a></h3><p><strong>Si gagner cette manche permet de gagner la partie :</strong></p><ul><li>Soyez plus conservateur</li><li>Ne prenez pas le risque de concéder plusieurs points.</li><li>Un seul point pourrait suffire.</li></ul><p><strong>Si la défaite à ce niveau entraîne la défaite :</strong></p><ul><li>Prendre plus de risques</li><li>Il faut marquer plusieurs points</li><li>Le jeu prudent ne vous sauvera pas.</li></ul><h2 id="erreurs-courantes-en-matiere-de-probabilites" tabindex="-1">Erreurs courantes en matière de probabilités <a class="header-anchor" href="#erreurs-courantes-en-matiere-de-probabilites" aria-label="Permalink to &quot;Erreurs courantes en matière de probabilités&quot;">​</a></h2><h3 id="_1-exces-de-confiance" tabindex="-1">1. Excès de confiance <a class="header-anchor" href="#_1-exces-de-confiance" aria-label="Permalink to &quot;1. Excès de confiance&quot;">​</a></h3><p>« Je peux réussir ce tir » – mais pouvez-vous le réussir 7 fois sur 10 ? Soyez honnête.</p><h3 id="_2-ignorer-les-taux-de-base" tabindex="-1">2. Ignorer les taux de base <a class="header-anchor" href="#_2-ignorer-les-taux-de-base" aria-label="Permalink to &quot;2. Ignorer les taux de base&quot;">​</a></h3><p>Votre pourcentage de réussite au tir ne change pas parce que le moment est important.</p><h3 id="_3-erreur-des-couts-irrecuperables" tabindex="-1">3. Erreur des coûts irrécupérables <a class="header-anchor" href="#_3-erreur-des-couts-irrecuperables" aria-label="Permalink to &quot;3. Erreur des coûts irrécupérables&quot;">​</a></h3><p>« J&#39;ai déjà raté deux fois, je devrais continuer à tirer » - chaque lancer est indépendant.</p><h3 id="_4-biais-de-resultat" tabindex="-1">4. Biais de résultat <a class="header-anchor" href="#_4-biais-de-resultat" aria-label="Permalink to &quot;4. Biais de résultat&quot;">​</a></h3><p>Un coup risqué qui réussit reste risqué. Une action prudente qui échoue reste la bonne.</p><h3 id="_5-ignorer-les-options-de-l-39-adversaire" tabindex="-1">5. Ignorer les options de l&#39;adversaire <a class="header-anchor" href="#_5-ignorer-les-options-de-l-39-adversaire" aria-label="Permalink to &quot;5. Ignorer les options de l&amp;#39;adversaire&quot;">​</a></h3><p>Réfléchissez à ce qu&#39;ils feront après votre lancer, réussi ou non.</p><h2 id="application-pratique" tabindex="-1">Application pratique <a class="header-anchor" href="#application-pratique" aria-label="Permalink to &quot;Application pratique&quot;">​</a></h2><h3 id="avant-chaque-lancer" tabindex="-1">Avant chaque lancer <a class="header-anchor" href="#avant-chaque-lancer" aria-label="Permalink to &quot;Avant chaque lancer&quot;">​</a></h3><ol><li><strong>Identifier les options</strong> (pointer, tirer, bloquer, etc.)</li><li><strong>Estimer la probabilité de succès</strong> pour chaque</li><li><strong>Tenez compte des résultats</strong> (succès et échec)</li><li><strong>Tenir compte de l&#39;état du jeu</strong> (score, boules restantes)</li><li><strong>Choisissez</strong> l&#39;option présentant la meilleure valeur attendue</li><li><strong>Engagez-vous pleinement</strong> - sans hésitation lors de l&#39;exécution</li></ol><h3 id="developper-son-intuition" tabindex="-1">Développer son intuition <a class="header-anchor" href="#developper-son-intuition" aria-label="Permalink to &quot;Développer son intuition&quot;">​</a></h3><p>Avec le temps, le raisonnement probabiliste devient intuitif :</p><ul><li>Suivez vos résultats honnêtement</li><li>Révision des décisions après les matchs</li><li>Observez les tendances dans vos taux de réussite.</li><li>Modifiez votre modèle mental</li></ul><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><blockquote><p>Les bonnes décisions n&#39;aboutissent pas toujours à de bons résultats. Mais, sur le long terme, les bonnes décisions permettent d&#39;obtenir de meilleurs résultats.</p></blockquote><p>Réfléchissez en termes de probabilités. Maîtrisez vos chiffres. Faites le choix judicieux, pas celui qui repose sur l&#39;espoir.</p>',59))])}]]);export{c as __pageData,p as default};
